#!/usr/bin/env python3\n"""Patch a legally obtained Geometry Dash client binary for a MuchoCore GDPS."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport base64\nimport pathlib\nimport sys\n\nPLAIN_DATABASE = b"https://www.boomlings.com/database"\n\n\ndef b64(value: str) -> bytes:\n    return base64.b64encode(value.encode("ascii"))\n\n\ndef replace_exact(data: bytes, old: bytes, new: bytes, label: str) -> tuple[bytes, int]:\n    if len(new) != len(old):\n        raise ValueError(\n            f"{label}: replacement length mismatch "\n            f"(original={len(old)}, replacement={len(new)})."\n        )\n    count = data.count(old)\n    if count == 0:\n        return data, 0\n    return data.replace(old, new), count\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(\n        description="Patch a Geometry Dash client binary for a MuchoCore GDPS."\n    )\n    parser.add_argument("--input", help="Original client binary. If omitted, you will be asked.")\n    parser.add_argument("--output", help="Patched output. If omitted, it is created next to the input.")\n    parser.add_argument("--server-url", help="Public MuchoCore server URL, for example https://gdps.example.com")\n    parser.add_argument("--skip-http-base64", action="store_true", help="Do not attempt legacy HTTP Base64 replacements.")\n    args = parser.parse_args()\n\n    input_value = args.input or input("Path to your Geometry Dash client: ").strip()\n    server_value = args.server_url or input("MuchoCore server URL (for example https://gdps.example.com): ").strip()\n    if not input_value or not server_value:\n        print("ERROR: input file and server URL are required.", file=sys.stderr)\n        return 2\n\n    input_path = pathlib.Path(input_value)\n    output_path = pathlib.Path(args.output) if args.output else input_path.with_name(input_path.stem + "-MuchoCore" + input_path.suffix)\n    server = server_value.rstrip("/")\n\n    if not server.startswith(("http://", "https://")):\n        print("ERROR: server URL must start with http:// or https://", file=sys.stderr)\n        return 2\n\n    database_url = server + "/database"\n    http_server = server.replace("https://", "http://", 1)\n    http_database = http_server + "/database"\n\n    if not input_path.is_file():\n        print(f"ERROR: input file does not exist: {input_path}", file=sys.stderr)\n        return 2\n    if output_path.resolve() == input_path.resolve():\n        print("ERROR: output must be a different file from input.", file=sys.stderr)\n        return 2\n\n    if len(database_url.encode("ascii")) != len(PLAIN_DATABASE):\n        print(\n            "ERROR: the HTTPS database URL must be exactly 34 bytes long for this client.",\n            file=sys.stderr,\n        )\n        print(f"Your URL: {database_url} ({len(database_url.encode('ascii'))} bytes)")\n        print("Choose a different domain/subdomain and try again.")\n        return 2\n\n    data = input_path.read_bytes()\n    original_size = len(data)\n    replacements: dict[str, int] = {}\n\n    try:\n        data, n = replace_exact(data, PLAIN_DATABASE, database_url.encode("ascii"), "HTTPS database URL")\n        replacements["HTTPS database URL"] = n\n\n        if not args.skip_http_base64:\n            replacements["Base64 HTTP /database"] = 0\n            replacements["Base64 HTTP root"] = 0\n\n            old = b64("http://www.boomlings.com/database")\n            new = b64(http_database)\n            if len(new) == len(old):\n                data, n = replace_exact(data, old, new, "Base64 HTTP /database")\n                replacements["Base64 HTTP /database"] = n\n            else:\n                print("INFO: legacy Base64 HTTP /database skipped because its length does not match.")\n\n            old = b64("http://www.boomlings.com/")\n            new = b64(http_server + "/")\n            if len(new) == len(old):\n                data, n = replace_exact(data, old, new, "Base64 HTTP root")\n                replacements["Base64 HTTP root"] = n\n            else:\n                print("INFO: legacy Base64 HTTP root skipped because its length does not match.")\n    except (UnicodeEncodeError, ValueError) as exc:\n        print(f"ERROR: {exc}", file=sys.stderr)\n        return 2\n\n    if replacements["HTTPS database URL"] == 0:\n        print("ERROR: the standard HTTPS database URL was not found in this client.", file=sys.stderr)\n        print("Stop here and verify that this is the expected 2.2 client build.", file=sys.stderr)\n        return 3\n\n    output_path.parent.mkdir(parents=True, exist_ok=True)\n    output_path.write_bytes(data)\n\n    print()\n    print("MuchoCore client patch complete.")\n    print(f"Input:  {input_path}")\n    print(f"Output: {output_path}")\n    print(f"Server: {server}")\n    print()\n    print("You can now test the patched client.")\n    for name, count in replacements.items():\n        print(f"{name}: {count} replacement(s)")\n\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n